'use strict';
/* MICRO Q1164 FAST WR OPTIMIZER — precompute candidate features once */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(p){let a=new Float64Array(M.length),k=2/(p+1),x=M[0].c;for(let i=0;i<M.length;i++){x=i?M[i].c*k+x*(1-k):x;a[i]=x}return a}function atr(p=14){let a=new Float64Array(M.length);for(let i=p;i<M.length;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));a[i]=s/p}return a}const E9=ema(9),E21=ema(21),E50=ema(50),A=atr();
const C=[];for(let i=60;i<M.length-1;i++){let b=M[i],a=A[i];if(!(a>0)||!(E9[i]>E21[i]&&E21[i]>E50[i]&&E21[i]>E21[i-3]))continue;let rg=b.h-b.l;if(!(rg>0))continue;let body=Math.abs(b.c-b.o)/rg,pos=(b.c-b.l)/rg,sep=Math.abs(E9[i]-E21[i])/a;if(body<.65||pos<.78||sep<.15||b.c<=M[i-1].h)continue;let is=i-4,ie=i-2,raw=M[ie].c-M[is].o,imp=raw/a;if(!(raw>0)||imp<1.3)continue;let pl=Infinity;for(let j=ie+1;j<i;j++)pl=Math.min(pl,M[j].l);let retr=(M[ie].c-pl)/raw;if(retr<.12||retr>.45)continue;C.push({i,t:b.t,h:new Date(b.t).getUTCHours(),sep,imp,body,pos,retr})}
function sel(q){let B=new Set(q.block);return C.filter(x=>!B.has(x.h)&&x.sep>=q.sep&&x.imp>=q.imp&&x.body>=q.body&&x.pos>=q.pos&&x.retr>=q.rmin&&x.retr<=q.rmax)}function trades(q){let sig=new Set(sel(q).map(x=>x.i)),out=[],p=null;for(let i=60;i<M.length;i++){if(p){let b=M[i],sl=b.l<=p.sl,tp=b.h>=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c;out.push({t:M[p.si].t,r:(px-p.en)/p.risk});p=null}if(p)continue}let si=i-1;if(sig.has(si)){let en=M[i].o,risk=2*A[si];p={en,risk,sl:en-risk,tp:en+risk,ei:i,si}}}return out}function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const split=M[Math.floor(M.length*.70)].t,base={block:[16,17,20],sep:.15,imp:1.3,body:.65,pos:.78,rmin:.12,rmax:.45},BT=trades(base),bsd=S(BT.filter(x=>x.t<split)),bsh=S(BT.filter(x=>x.t>=split));console.log('MICRO Q1164 — FAST WR OPTIMIZER');console.log(`M5 ${M.length} | raw candidates ${C.length}`);console.log('BASE DEV ',F(bsd));console.log('BASE HOLD',F(bsh));console.log('BASE ALL ',F(S(BT)),'\n');
const EB=[[],[13],[14],[15],[18],[19],[21],[22],[13,19],[14,19],[15,19],[18,19],[19,21],[13,21],[14,21]],SE=[.15,.18,.21,.24],IM=[1.3,1.4,1.5,1.6],BO=[.65,.70,.75],PO=[.78,.82,.86],RE=[[.12,.45],[.12,.40],[.12,.35],[.16,.45],[.16,.40],[.20,.45],[.20,.40]];let uniq=new Map(),grid=0;for(const eb of EB)for(const sep of SE)for(const imp of IM)for(const body of BO)for(const pos of PO)for(const [rmin,rmax] of RE){grid++;let q={block:[...new Set([16,17,20,...eb])],sep,imp,body,pos,rmin,rmax},s=sel(q);if(s.length<100)continue;let key=s.map(x=>x.i).join(',');if(!uniq.has(key))uniq.set(key,q)}console.log(`Grid ${grid} -> unique eligible signal sets ${uniq.size}`);let rows=[],id=0;for(const q of uniq.values()){id++;let T=trades(q),D=T.filter(x=>x.t<split),H=T.filter(x=>x.t>=split),sd=S(D),sh=S(H);if(sd.n<70||sd.n<bsd.n*.48)continue;let all=S(T),score=(sd.wr-bsd.wr)*1.2+(sd.pf-bsd.pf)*8+(bsd.dd-sd.dd)*1.5;rows.push({id,q,sd,sh,all,score})}rows.sort((a,b)=>b.score-a.score);const L=x=>`#${x.id} +B[${x.q.block.filter(h=>![16,17,20].includes(h)).join(',')||'-'}] SEP${x.q.sep} IMP${x.q.imp} BODY${x.q.body} POS${x.q.pos} RET${x.q.rmin}-${x.q.rmax} | DEV ${F(x.sd)} | HOLD ${F(x.sh)} | ALL ${F(x.all)}`;console.log('\n🏆 TOP 20 DEV');rows.slice(0,20).forEach(x=>console.log(L(x)));let robust=rows.filter(x=>x.sd.wr>=bsd.wr+3&&x.sd.pf>=bsd.pf&&x.sd.dd<=bsd.dd&&x.sh.n>=25&&x.sh.wr>=bsh.wr&&x.sh.pf>=bsh.pf*.95&&x.sh.dd<=bsh.dd*1.10&&x.all.wr>=62&&x.all.pf>=1.45&&x.all.n>=120);console.log('\n🛡️ ROBUST WR SHORTLIST');if(!robust.length)console.log('NONE — keep Q1164 unchanged.');else robust.slice(0,15).forEach(x=>console.log(L(x)));
